export function posterDimensions(width,height){if(!width||!height||width*height>50000000)throw new Error('ภาพมีขนาดใหญ่เกินไป กรุณาเลือกภาพเล็กลง');const scale=Math.min(1,1200/width,1600/height);return {width:Math.max(1,Math.round(width*scale)),height:Math.max(1,Math.round(height*scale))}}
export function mountPosterPicker(root){
 const wrapper=document.createElement('div');wrapper.className='poster-picker';wrapper.innerHTML='<label>ภาพโปสเตอร์ (ไม่บังคับ)<input type="file" accept="image/jpeg,image/png,image/webp"></label><p class="sub">แนวตั้งประมาณ 3:4 · JPG, PNG หรือ WebP ไม่เกิน 15 MB ระบบย่อให้โดยไม่ตัดภาพ</p><img alt="ตัวอย่างโปสเตอร์" hidden><p role="status"></p>';root.append(wrapper);
 const input=wrapper.querySelector('input'),preview=wrapper.querySelector('img'),status=wrapper.querySelector('[role=status]');let blob=null,processing=null,serial=0;
 input.onchange=()=>{const current=++serial;blob=null;preview.hidden=true;const file=input.files[0];if(!file){status.textContent='';processing=null;return}processing=(async()=>{let url;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024)throw new Error('กรุณาเลือก JPG, PNG หรือ WebP ไม่เกิน 15 MB');status.textContent='กำลังเตรียมภาพ…';url=URL.createObjectURL(file);const img=new Image();img.src=url;await img.decode();const size=posterDimensions(img.naturalWidth,img.naturalHeight),canvas=document.createElement('canvas');canvas.width=size.width;canvas.height=size.height;const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,size.width,size.height);ctx.drawImage(img,0,0,size.width,size.height);const output=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.85));if(!output||output.size>2*1024*1024)throw new Error('ย่อภาพไม่สำเร็จ กรุณาเลือกภาพเล็กลง');if(current!==serial)return;blob=output;preview.src=canvas.toDataURL('image/jpeg',0.85);preview.hidden=false;status.textContent='ภาพพร้อมบันทึก'}catch(error){if(current===serial)status.textContent=error.message;throw error}finally{if(url)URL.revokeObjectURL(url)}})();processing.catch(()=>{});};
 return {async upload(client,eventId){if(processing)await processing;if(blob){await client.uploadPoster(eventId,blob);return true}return false},setDisabled(value){input.disabled=value}};
}
export function mountPosterSettings(root,client,eventId){const panel=document.createElement('div');panel.className='panel';panel.innerHTML='<h3>โปสเตอร์กิจกรรม</h3>';root.append(panel);const picker=mountPosterPicker(panel),button=document.createElement('button'),status=document.createElement('p');status.setAttribute('role','status');button.textContent='บันทึกโปสเตอร์';panel.append(button,status);button.onclick=async()=>{button.disabled=true;picker.setDisabled(true);status.textContent='กำลังบันทึก…';try{if(!await picker.upload(client,eventId))throw new Error('กรุณาเลือกภาพก่อนบันทึก');status.textContent='บันทึกแล้ว เปิดหน้ากิจกรรมเพื่อดูโปสเตอร์'}catch(error){status.textContent=error.message||'บันทึกไม่ได้ กดลองใหม่'}finally{button.disabled=false;picker.setDisabled(false)}}}
